const lang=document.documentElement.lang==='en'?'en':'th';let catalogue;
const getCatalog=()=>catalogue??=fetch('/site-catalog.json').then(r=>{if(!r.ok)throw Error('catalogue');return r.json()});
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const menu=document.querySelector('#site-menu'),search=document.querySelector('#site-search'),toggle=document.querySelector('.site-menu-toggle');
function lock(){document.body.classList.toggle('overlay-open',Boolean(menu&&!menu.hidden||search&&!search.hidden))}
async function openMenu(key){const data=await getCatalog();menu.querySelector('.menu-groups').innerHTML=data.groups.map((g,i)=>`<section class="menu-group ${key===g.key?'menu-highlight':''}"><h2><span>0${i+1}</span>${esc(g[lang])}</h2><div>${[...new Map(data.pages.filter(p=>p.lang===lang&&p.navigable&&p.group===g.key&&!['/th/home','/en/home'].includes(p.path)).map(p=>[p.title,p])).values()].map(p=>`<a href="${esc(p.href)}">${esc(p.title)}<span>↗</span></a>`).join('')}</div></section>`).join('');menu.hidden=false;toggle?.setAttribute('aria-expanded','true');lock();menu.querySelector('[data-menu-close]').focus();if(key)menu.querySelector('.menu-highlight')?.scrollIntoView({block:'nearest'})}
document.querySelectorAll('[data-menu-group]').forEach(b=>b.addEventListener('click',()=>openMenu(b.dataset.menuGroup)));
toggle?.addEventListener('click',()=>menu.hidden?openMenu():close());
function close(){if(menu)menu.hidden=true;if(search)search.hidden=true;toggle?.setAttribute('aria-expanded','false');lock()}
document.querySelector('[data-menu-close]')?.addEventListener('click',close);document.querySelector('[data-search-close]')?.addEventListener('click',close);
document.querySelector('[data-search-open]')?.addEventListener('click',()=>{search.hidden=false;lock();document.querySelector('#global-search').focus()});
document.addEventListener('keydown',e=>{if(e.key==='Escape')close();if(e.key==='Tab'&&(!menu?.hidden||!search?.hidden)){const panel=!search?.hidden?search:menu;const nodes=[...panel.querySelectorAll('button,a[href],input')].filter(n=>n.offsetParent!==null);if(!nodes.length)return;const first=nodes[0],last=nodes.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});
function resultCards(items){return `<div class="page-card-grid">${items.map(p=>`<a class="page-card" href="${esc(p.href)}">${p.image&&!p.image.includes('opengraph')?`<div class="page-card-image"><img src="${esc(p.image)}" alt="" loading="lazy"/></div>`:''}<span class="page-card-kicker">${p.document?'DOCUMENT':esc(p.group.replaceAll('-',' ').toUpperCase())}</span><h3>${esc(p.title)}</h3><p>${esc(p.description.slice(0,170))}</p><span class="page-card-arrow">↗</span></a>`).join('')}</div>`}
async function query(input,target){const data=await getCatalog(),q=input.value.trim().toLocaleLowerCase();const all=data.pages.filter(p=>p.lang===lang&&(q?(p.title+' '+p.description).toLocaleLowerCase().includes(q):p.primary));target.innerHTML=`<p class="result-count">${lang==='th'?'พบ':'Found'} ${all.length} ${lang==='th'?'รายการ':'results'}</p>`+resultCards(all.slice(0,60));}
document.querySelector('#global-search')?.addEventListener('input',e=>query(e.target,document.querySelector('#global-results')));
const pageSearch=document.querySelector('#page-query');if(pageSearch){pageSearch.addEventListener('input',()=>query(pageSearch,document.querySelector('.page-search .archive-results')));query(pageSearch,document.querySelector('.page-search .archive-results'))}
document.querySelectorAll('[data-archive-path]').forEach(async node=>{const data=await getCatalog();const current=data.pages.find(p=>p.path===node.dataset.archivePath);const paths=new Set(current?.resources??[]);const items=data.pages.filter(p=>paths.has(p.path));let count=12;const input=node.querySelector('input'),more=node.querySelector('.archive-more');function draw(){const q=input.value.trim().toLocaleLowerCase();const filtered=items.filter(p=>(p.title+' '+p.description).toLocaleLowerCase().includes(q));node.querySelector('.archive-count').textContent=`${filtered.length} ${lang==='th'?'รายการ':'items'}`;node.querySelector('.archive-results').innerHTML=resultCards(filtered.slice(0,count));more.hidden=count>=filtered.length}input.addEventListener('input',()=>{count=12;draw()});more.addEventListener('click',()=>{count+=12;draw()});draw()});
document.querySelectorAll('[data-directory]').forEach(async node=>{const data=await getCatalog();node.innerHTML=data.groups.map(g=>`<section><h2>${esc(g[lang])}</h2><div class="directory-links">${data.pages.filter(p=>p.lang===lang&&p.navigable&&p.group===g.key).map(p=>`<a href="${esc(p.href)}">${esc(p.title)} ↗</a>`).join('')}</div></section>`).join('')});
document.querySelectorAll('.source-body [data-toggle="tab"]').forEach(a=>a.addEventListener('click',e=>{const id=a.getAttribute('href');if(!id?.startsWith('#'))return;const target=document.getElementById(id.slice(1));if(!target)return;e.preventDefault();const parent=target.parentElement;parent.querySelectorAll(':scope > .tab-pane').forEach(p=>p.hidden=p!==target);a.closest('ul')?.querySelectorAll('[data-toggle="tab"]').forEach(t=>t.classList.toggle('active',t===a));target.hidden=false}));
document.querySelectorAll('.source-body .tab-content').forEach(node=>{const panes=[...node.querySelectorAll(':scope > .tab-pane')];if(panes.length)panes.forEach((p,i)=>p.hidden=!(p.classList.contains('active')||i===0))});
getCatalog().then(data=>{const current=location.pathname.replace(/\/$/,'');const page=data.pages.find(p=>p.href.replace(/\/$/,'')===current);const other='/'+(lang==='th'?'en':'th')+'/'+(page?.path.split('/').slice(2).join('/')||'home');const alternate=data.pages.find(p=>p.path===other);const link=document.querySelector('#language-switch');if(link)link.href=alternate?.href||`/${lang==='th'?'en':'th'}/home/`;}).catch(()=>{});
if(!matchMedia('(prefers-reduced-motion: reduce)').matches){const visible=new IntersectionObserver(entries=>{for(const e of entries)if(e.isIntersecting){e.target.classList.add('page-in');visible.unobserve(e.target)}},{threshold:.08});document.querySelectorAll('.source-body .card-board,.related-pages .page-card').forEach(el=>{el.classList.add('page-animate');visible.observe(el)})}
